      "merge_nodes",
      "add_parent",
      "remove_parent"
    ],
    "stage_commit_definition": "Operations that finalize local staged node state or perform canonical graph topology mutations.",
    "stage_commit_vs_other_mutating": "Other mutating tools (sharing, artifacts, compute, executions, campaign budgets) can change related state but do not define core node stage/commit and topology transitions.",
    "commit_contract": {
      "request_contract": {
        "required_fields": [
          "stage_session_id",
          "base_committed_revision",
          "staged_payload"
        ],
        "staged_payload_required_fields": [
          "title",
          "content",
          "summary",
          "repo_context"
        ],
        "repo_context_required_fields": [
          "repo_url",
          "branch_name",
          "head_commit_sha",
          "origin_host",
          "updated_by",
          "external_transcript_ref"
        ]
      },
      "result_node_requirements": {
        "required_fields": [
          "title",
          "content",
          "summary"
        ],
        "typed_body_fields": "removed"
      },
      "staged_change_status_fields": {
        "staged_changes_pending": "bool",
        "commit_required": "bool",
        "next_action_hint": "str"
      },
      "local_temp_node_id_requirements": {
        "scope": "caller-local",
        "canonical_node_id_rule": "commit_new_node.local_temp_node_id must be a caller-local temporary ID and must not be an existing canonical node_id visible to the caller.",
        "branch_node_guidance": "branch_node returns a canonical child branch node. Edit that node with a stage lease and commit_node instead of reusing its node_id as a commit_new_node local temp ID."
      },
      "write_shape_guidance": {
        "canonical_body_fields": [
          "title",
          "content",
          "summary"
        ],
        "removed_body_fields_rejected": [
          "kind",
          "node_type",
          "hypothesis",
          "insights",
          "no_artifacts_reason"
        ],
        "no_repo_context_note": "repo_context is required in the write payload. For nodes with no repository context, pass the required repo_context keys with null values."
      },
      "minimal_commit_new_node_payload": {
        "local_temp_node_id": "local-root-1",
        "parent_ids": [],
        "staged_payload": {
          "title": "Minimal node",
          "content": "",
          "summary": "",
          "repo_context": {
            "repo_url": null,
            "branch_name": null,
            "head_commit_sha": null,
            "origin_host": null,
            "updated_by": null,
            "external_transcript_ref": null
          }
        }
      },
      "conflict_behavior": {
        "status_code": 409,
        "detail_type": "conflict_error",
        "stale_base_committed_revision_message": "stale committed revision",
        "missing_stage_lease_message": "stage lease missing or expired"
      },
      "retry_idempotency": {
        "safe_retry": "Resend the same commit request with the same idempotency key to replay the prior success response.",
        "payload_mismatch": "Reusing an idempotency key with different request content returns 409."
      }
    },
    "guidance": {
      "git_alignment": "share repo metadata and align branch/code lineage with graph topology where practical",
      "reproducibility": "content, summaries, and artifacts should provide enough detail for third-party reproduction/audit"
    },
    "durable_contract_rules": [
      "Node-body staging for `commit_new_node` and `commit_node` is caller-local until commit, while graph topology operations such as `branch_node`, `merge_nodes`, `add_parent`, and `remove_parent` are canonical mutations when they succeed.",
      "Mutating node writes are optimistic-locking operations: read latest state, pass `expected_revision` or `base_committed_revision` as required, and handle `409 conflict` with explicit reconciliation.",
      "Mutating operations are idempotent; MCP tool transport auto-manages `Idempotency-Key` on mutating tool calls.",
      "Existing-node field editing may use a session-scoped stage lease (`flywheel_acquire_stage_lease`, `flywheel_heartbeat_stage_lease`, `flywheel_release_stage_lease`) to coordinate local staged state before commit.",
      "Existing-node commit publishes a full staged payload under an active stage lease: commit requests require `stage_session_id`, `base_committed_revision`, and `staged_payload`; conflicts on stale committed revisions are surfaced directly and are not transport-retried.",
      "Commit responses expose `staged_changes_pending`, `commit_required`, and `next_action_hint` so clients can distinguish saved canonical state from local staged work.",
      "Committed node state uses the same canonical body fields for every node; summary may be empty when the node body is intentionally represented by content, artifacts, tags, or executions.",
      "When code is involved, pass `repo_url`/`branch_name`/`head_commit_sha` and align git structure with graph topology where practical (without forcing one-to-one mapping).",
      "Content, summaries, and artifacts should be reproduction-grade: enough setup, method, evidence, and interpretation for another reader to reproduce or audit results.",
      "Execution workflow should launch execution, inspect outcomes, publish evidence artifacts, and commit only after terminal status."
    ]
  }
}

