      "title": {
        "required_non_empty": true,
        "display_label_field": "title",
        "normalization_priority": [
          "explicit_title",
          "payload.title",
          "payload.name",
          "basename(payload.path|payload.filename|payload.file)",
          "basename(filename)",
          "basename(storage_path)",
          "artifact_type",
          "artifact"
        ],
        "must_not_derive_from": [
          "storage_url"
        ]
      },
      "storage_url": {
        "purpose": "raw_artifact_byte_read_url",
